    static func chrome(_ i: InkRGB) -> [String: RGB] {
        ["bg": i.bg, "rail": i.rail, "surface": i.bg1, "raised": i.bg2, "hover": i.hover, "hoverRail": i.hoverRail, "selected": i.selected,
         "fg1": i.fg, "fg2": i.fg2, "fg3": i.fg3, "fg4": i.fg4, "hourc": i.hourLabel, "accent": i.fg, "onAccent": i.bg, "live": i.live,
         "onLive": i.onLive, "focus": i.focus, "ok": i.ok, "warn": i.warn, "danger": i.danger, "segRing": i.segRing, "grid": i.grid,
         "gridV": i.gridV, "hairStrong": i.hairStrong, "hair": i.hair, "todayTint": i.todayTint]
    }

    static func recipe(_ hex: String, dark: Bool) -> [String: String] {
        let e = dark ? EventRecipe.dark(C8(hex: hex)) : EventRecipe.paper(C8(hex: hex))
        return ["fill": e.fill.hex, "fillH": e.fillH.hex, "fillSel": e.fillSel.hex, "bar": e.bar.hex, "title": e.title.hex, "titleSel": e.titleSel.hex,
                "meta": e.meta.hex, "metaSel": e.metaSel.hex, "fillPast": e.fillPast.hex, "titlePast": e.titlePast.hex, "metaPast": e.metaPast.hex,
                "barPast": e.barPast.hex, "fillDec": e.fillDec.hex, "titleDec": e.titleDec.hex, "edge": e.edge.hex]
    }

    @Test func chromeTokensAreTheMockups() {
        for (ink, want) in [(InkRGB.dark, Mockup.darkChrome), (InkRGB.light, Mockup.paperChrome)] {
            let ours = Self.chrome(ink)
            #expect(Set(ours.keys) == Set(want.keys))
            for (k, hex) in want { #expect(ours[k] == RGB(hex: hex), "\(ink == .dark ? "dark" : "paper") \(k): \(ours[k]?.c8.hex ?? "-") != \(hex)") }
        }
    }

    @Test(arguments: [true, false]) func eventRecipeIsTheMockups(dark: Bool) {
        let want = dark ? Mockup.darkEvents : Mockup.paperEvents
        for (hex, w) in want {
            let ours = Self.recipe(hex, dark: dark)
            for (k, v) in w { #expect(ours[k] == v, "\(dark ? "dark" : "paper") \(hex) \(k): \(ours[k] ?? "-") != \(v)") }
        }
    }

    @Test func foundationsSamples() {
        // design/design-system/foundations.md: Personal #5B8DEF in Dark, swatches in Paper (fill / bar).
        let d = EventRecipe.dark(C8(hex: "#5B8DEF"))
        #expect(d.fill.hex == "#162A50" && d.title.hex == "#FFFFFF" && d.meta.hex == "#C9DCFE")
        for (hex, fill, bar) in [("#5B8DEF", "#D1E1FE", "#3970E0"), ("#A9A6F5", "#E2E2FE", "#715EE0"), ("#9254DE", "#DFD5F2", "#9049E1"),
                                 ("#B9B9B9", "#E1E1E1", "#959595"), ("#E9B949", "#F6E6C3", "#BB8D01"), ("#D9443A", "#F6D2CC", "#DB1E1D")] {
            let p = EventRecipe.paper(C8(hex: hex))
            #expect(p.fill.hex == fill && p.bar.hex == bar, "\(hex): \(p.fill.hex) / \(p.bar.hex)")
        }
    }

    @Test func paperFillsReadAsTheirColour() {
        // Clear tint: every coloured calendar fill at least ΔE_OK 7.5 from the canvas.
        for (hex, _) in Mockup.paperEvents where hex != "#888888" {
            #expect(ColorMath.deltaE(EventRecipe.paper(C8(hex: hex)).fill, InkRGB.light.bg.c8) >= 7.5, "\(hex)")
        }
    }

