        "status": Floor(ratio: 4.5, lc: 45), "nontext": Floor(ratio: 3, lc: 0), "evTitle": Floor(ratio: 7, lc: 75), "evMeta": Floor(ratio: 6.5, lc: 60),
        "evSelMeta": Floor(ratio: 5.5, lc: 55), "evPastTitle": Floor(ratio: 7, lc: 65), "evPastMeta": Floor(ratio: 5.7, lc: 48), "evDecl": Floor(ratio: 6, lc: 55),
        "decor": Floor(ratio: 1, lc: 0, max: 15), "structure": Floor(ratio: 1.15, lc: 0, max: 35)]
    static let floorsPaper: [String: Floor] = [
        "fg1": Floor(ratio: 12, lc: 95), "fg1soft": Floor(ratio: 12, lc: 88), "fg2": Floor(ratio: 7, lc: 80), "fg2soft": Floor(ratio: 7, lc: 75),
        "fg3": Floor(ratio: 5, lc: 70), "fg3soft": Floor(ratio: 5, lc: 65), "accent": Floor(ratio: 12, lc: 90), "live": Floor(ratio: 4.5, lc: 60),
        "status": Floor(ratio: 4.5, lc: 60), "nontext": Floor(ratio: 3, lc: 0), "evTitle": Floor(ratio: 7, lc: 75), "evMeta": Floor(ratio: 5.9, lc: 70),
        "evSelMeta": Floor(ratio: 5.5, lc: 65), "evPastTitle": Floor(ratio: 7, lc: 75), "evPastMeta": Floor(ratio: 5, lc: 65), "evDecl": Floor(ratio: 6.5, lc: 75),
        "decor": Floor(ratio: 1, lc: 0, max: 15), "structure": Floor(ratio: 1.15, lc: 0, max: 35)]

    struct Pair { var what: String, fg: RGB, bg: RGB, key: String }

    /// readability.js `pairs()` / `pairsP()` for the locked design, plus every block state as `BlockColors` draws it.
    static func pairs(dark: Bool) -> [Pair] {
        let t = InkRGB.of(dark)
        var P: [Pair] = []
        func A(_ w: String, _ fg: RGB, _ bg: RGB, _ k: String) { P.append(Pair(what: w, fg: fg, bg: bg, key: k)) }
        let canvas: [(String, RGB)] = dark ? [("bg", t.bg), ("rail", t.rail)] : [("bg", t.bg), ("rail", t.rail), ("raised", t.bg2)]
        for (n, b) in canvas {
            A("fg1 on \(n)", t.fg, b, dark && ColorMath.relL(b.c8) >= 0.01 ? "fg1soft" : "fg1"); A("fg2 on \(n)", t.fg2, b, "fg2"); A("fg3 on \(n)", t.fg3, b, "fg3")
        }
        var soft: [(String, RGB)] = [("surface", t.bg1), ("hover", t.hover), ("hover on rail", t.hoverRail), ("selected", t.selected), ("today column", t.todayTint)]
        if dark { soft.append(("raised", t.bg2)) }
        for (n, b) in soft { A("fg1 on \(n)", t.fg, b, "fg1soft"); A("fg2 on \(n)", t.fg2, b, "fg2soft"); A("fg3 on \(n)", t.fg3, b, "fg3soft") }
        A("hour labels on bg", t.hourLabel, t.bg, "fg3")
        A("today date / primary button", t.bg, t.fg, "accent")
        A("now pill text on live red", t.onLive, t.live, "live")
        for (n, b) in [("bg", t.bg), ("rail", t.rail), ("card", t.bg1)] { A("live text on \(n)", t.live, b, "live") }
        A("now line vs bg", t.live, t.bg, "nontext")
        A("focus ring vs bg", t.focus, t.bg, "nontext"); A("focus ring vs raised", t.focus, t.bg2, "nontext")
        A("selected segment edge vs track", t.segRing, t.bg1, "nontext")
        for (n, h) in [("ok", t.ok), ("warn", t.warn), ("danger", t.danger)] { A("\(n) text on bg", h, t.bg, "status") }
        A("hour line on bg", t.grid, t.bg, "structure"); A("hour line on today column", t.grid, t.todayTint, "structure")
        A("day divider", t.gridV, t.bg, "decor")
        A("all-day edge", t.hairStrong, t.bg, "structure"); A("pane edge", t.hair, t.bg, "decor")
        A("Join button text", t.fg, t.bg2, "accent")
        for (hex, _) in Mockup.darkEvents {
            let e = Palettes.palette(barHex: hex, fillHex: nil, dark: dark)
            A("event title · \(hex)", e.titleRGB, e.fillRGB, "evTitle"); A("event time · \(hex)", e.timeRGB, e.fillRGB, "evMeta")
            A("title on hover · \(hex)", e.titleRGB, e.hoverFillRGB, "evTitle"); A("time on hover / hatch · \(hex)", e.timeRGB, e.hoverFillRGB, "evMeta")
            A("selected title · \(hex)", e.selTitleRGB, e.selFillRGB, "evTitle"); A("selected time · \(hex)", e.selTimeRGB, e.selFillRGB, "evSelMeta")
            A("past title · \(hex)", e.pastTitleRGB, e.pastFillRGB, "evPastTitle"); A("past time · \(hex)", e.pastTimeRGB, e.pastFillRGB, "evPastMeta")
            A("declined title · \(hex)", e.declTitleRGB, e.declFillRGB, "evDecl")
            A("needs-reply outline vs bg · \(hex)", e.edgeRGB, t.bg, "nontext")
            for reply in [EventReply.accepted, .maybe, .notAnswered, .declined] {
                for past in [false, true] {
                    let c = e.colors(reply: reply, past: past)
                    let key = reply == .declined ? "evDecl" : past ? "evPastTitle" : "evTitle"
                    A("block title \(reply) past=\(past) · \(hex)", c.title, c.fill, key)
                    if let s = c.stripe { A("block title on hatch \(reply) · \(hex)", c.title, s, key) }
                }
            }
        }
        return P
    }

    @Test(arguments: [true, false]) func everyLockedPairMeetsItsFloor(dark: Bool) {
        let F = dark ? Self.floorsDark : Self.floorsPaper
        let all = Self.pairs(dark: dark)
        for p in all {
            let f = F[p.key]!, r = ColorMath.wcag(p.fg.c8, p.bg.c8), a = abs(ColorMath.apca(p.fg.c8, p.bg.c8))
            let ok = r >= f.ratio - 1e-9 && a >= f.lc - 0.05 && (f.max.map { a <= $0 + 0.05 } ?? true)
            #expect(ok, "\(dark ? "Dark" : "Paper") \(p.what): \(String(format: "%.2f:1 Lc %.1f", r, a)) misses \(p.key)")
        }
        #expect(all.count > 200)
    }

    // MARK: States

    let hex = "#5B8DEF"
    var pal: EventPalette { Palettes.palette(barHex: hex, fillHex: nil, dark: true) }

    @Test func statesPickTheRecipeColours() {
        let p = pal
        let n = p.colors(reply: .accepted, past: false)
        #expect(n.fill == p.fillRGB && n.bar == p.barRGB && n.title == p.titleRGB && n.time == p.timeRGB && n.barAlpha == 1 && !n.strike)
        let past = p.colors(reply: .accepted, past: true)
        #expect(past.fill == p.pastFillRGB && past.bar == p.pastBarRGB && past.title == p.pastTitleRGB && past.time == p.pastTimeRGB)
        let none = p.colors(reply: .notAnswered, past: false)
        // `.ev.st-none`: bg fill, fg1 title, fg2 time and the 1 pt hue outline (the painter draws no bar with an outline).
        #expect(none.fill == InkRGB.dark.bg && none.outline == p.edgeRGB && none.title == InkRGB.dark.fg && none.time == InkRGB.dark.fg2)
        let maybe = p.colors(reply: .maybe, past: false)
        #expect(maybe.fill == p.fillRGB && maybe.stripe == p.hoverFillRGB && p.colors(reply: .maybe, past: true).stripe == nil)
        let no = p.colors(reply: .declined, past: false)
        #expect(no.fill == p.declFillRGB && no.title == p.declTitleRGB && no.strike && no.barAlpha == 1)
    }

    @Test func hoverAndSelectionUseTheirFills() {
        var s = EventStyle(palette: pal, past: false, selected: false, overlapping: false)
        s.hovered = true
        #expect(s.colors.fill == pal.hoverFillRGB)
        s.selected = true
        #expect(s.colors.fill == pal.selFillRGB && s.colors.title == pal.selTitleRGB && s.colors.time == pal.selTimeRGB)
    }

    @Test func theEventColourReplacesTheCalendarColour() {
        let p = Palettes.palette(barHex: hex, fillHex: "#5FB97E", dark: true)
        #expect(p == Palettes.palette(barHex: "#5FB97E", fillHex: nil, dark: true))
        #expect(Palettes.cc(hex, dark: true) == EventRecipe.dark(C8(hex: hex)).mark.rgb)
    }

    @Test func fixtureRepliesMapToStates() {
        let m = makeModelV4()
        func reply(_ id: String) -> EventReply { EventReply(m.event(id: "v4.\(id)")!) }
        #expect(reply("w5") == .notAnswered && reply("w3") == .declined && reply("w2") == .maybe && reply("w1") == .accepted)
        #expect(reply("wg") == .accepted)              // Sam organises Flat dinner
        #expect(EventReply.declined.label == "declined" && EventReply.notAnswered.label == "no reply" && EventReply.maybe.label == "maybe")
    }

    @Test func titlesBreakAtSpacesFirstAndLongWordsHyphenate() {
        // As the browser does (mockup "Customer / interviews"): a space break wins when the word fits a line of its own.
        let w = TextCache.line("interviews", .title).width + 1
        #expect(TextCache.wrapTexts("Research interviews", .title, width: w, maxLines: 2, hyphenate: true) == ["Research", "interviews"])
        // A word wider than the line breaks at a syllable with a hyphen.
        let narrow = TextCache.line("Confer-", .title).width + 1
        let lines = TextCache.wrapTexts("Conference", .title, width: narrow, maxLines: 2, hyphenate: true)
        #expect(lines.count == 2 && lines[0].hasSuffix("-"), "\(lines)")
        let a = TextCache.wrapped("Conference", .title, width: narrow, maxLines: 2, hyphenate: true)
        let b = TextCache.wrapped("Conference", .title, width: narrow, maxLines: 2, hyphenate: true)
        #expect(a.count == 2 && a[0].line === b[0].line)
    }
